    public static void Main()
    {
        var package = new ExcelPackage(new FileInfo(@"C:\ExcelFile.xlsx"));
        ExcelWorksheet sheet = package.Workbook.Worksheets[1];

        var dataList = new List<ExcelData>();

        using (var stream = new FileStream("output.txt", FileMode.Create))
        using (var writer = ExcelWriterFactory.CreateWriter(stream, package.Workbook))
        {
            writer.WriteCell(stream, 0, 0, sheet.Columns[0].Name);
            writer.WriteCell(stream, 1, 0, sheet.Columns[1].Name);
            writer.WriteCell(stream, 2, 0, sheet.Columns[2].Name);

            for (int row = 2; row <= sheet.Dimension.End.Row; row++)
            {
                for (int col = 1; col <= sheet.Dimension.End.Column; col++)
                {
                    var cell = sheet.Cells[row, col];

                    if (cell.CellType == CellType.Blank)
                    {
